// Turns whatever a feed gives (hostname or URL) into a registrable domain using the same Public Suffix List
// copy the extension uses (ios/ShooExtension/Resources/psl.js, generated by Umar), so a published entry
// is exactly what the extension looks up. Returns null for anything that is not a plain public DNS name.
// TODO(sync:umar): psl.js is imported from ios/ShooExtension/Resources; if that folder moves, point this at the new copy.
import { PSL_RULES } from "../../../ios/ShooExtension/Resources/psl.js";
import { parseRules, registrableDomain as pslRegistrable } from "../../../ios/ShooExtension/Resources/domain.js";
import { isPublicHostname } from "../rdap/domain.js";

const RULES = parseRules(PSL_RULES);

function hostOf(raw) {
    let s = String(raw ?? "").trim().toLowerCase();
    if (!s || s.length > 2048) return null;
    if (s.includes("://")) {
        try {
            s = new URL(s).hostname;
        } catch {
            return null;
        }
    }
    s = s.replace(/\.+$/, "");
    return isPublicHostname(s) ? s : null;
}

/** True when `host` is itself a public suffix ("co.id", "github.io"): such a name must never be blocked. */
export function isPublicSuffix(host) {
    const probe = `a.${host}`;
    return pslRegistrable(probe, RULES) === probe;
}

/** @returns {string | null} e.g. "login.bca-x.co.id" -> "bca-x.co.id"; null for suffixes, IPs and junk */
export function toRegistrable(raw) {
    const host = hostOf(raw);
    if (!host) return null;
    if (isPublicSuffix(host)) return null;
    const reg = pslRegistrable(host, RULES);
    return reg && reg.includes(".") && isPublicHostname(reg) && !isPublicSuffix(reg) ? reg : null;
}
